"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { 
  Trophy, Users, Star, Crown, 
  Loader2, Search, Zap,
  TrendingUp, Award, Mail, Phone, Calendar,
  ListFilter, RefreshCcw, Store
} from "lucide-react";

export default function WaitlistIntelligencePage() {
  const [waitlistRank, setWaitlistRank] = useState<any[]>([]);
  const [vendorRank, setVendorRank] = useState<any[]>([]);
  const [fullRegistry, setFullRegistry] = useState<any[]>([]); 
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchIntelligence();
  }, []);

  async function fetchIntelligence() {
    setLoading(true);
    
    // 1. Fetch Top Waitlist Recruiters (The Champions)
    const { data: waitlistData } = await supabase
      .from('waitlist')
      .select('business_name, email, referral_count, created_at')
      .order('referral_count', { ascending: false })
      .limit(10);

    // 2. Fetch Top Vendor Recruiters (The Ambassadors)
    const { data: vendorData } = await supabase
      .from('stores')
      .select('name, referral_count, subscription_plan')
      .order('referral_count', { ascending: false })
      .limit(10);

    // 3. MASTER FETCH: Everyone on the Waitlist table
    const { data: waitlistEntries } = await supabase
      .from('waitlist')
      .select('business_name, email, phone, referral_count, created_at');

    // 4. MASTER FETCH: Everyone on the Stores table
    const { data: storeEntries } = await supabase
      .from('stores')
      .select('name, owner_email, whatsapp_number, referral_count, created_at');

    // --- 🛡️ DATA NORMALIZATION ---
    // We turn different column names into a single format for our table
    const combined = [
      ...(waitlistEntries || []).map(w => ({
        name: w.business_name || 'Anonymous Waitlist',
        contact_email: w.email,
        contact_phone: w.phone,
        score: w.referral_count || 0,
        joined_at: w.created_at,
        type: 'Waitlist'
      })),
      ...(storeEntries || []).map(s => ({
        name: s.name,
        contact_email: s.owner_email,
        contact_phone: s.whatsapp_number,
        score: s.referral_count || 0,
        joined_at: s.created_at,
        type: 'Live Vendor'
      }))
    ].sort((a, b) => new Date(b.joined_at).getTime() - new Date(a.joined_at).getTime());

    setWaitlistRank(waitlistData || []);
    setVendorRank(vendorData || []);
    setFullRegistry(combined);
    setLoading(false);
  }

  const filteredRegistry = fullRegistry.filter(entry => 
    entry.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    entry.contact_email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    entry.contact_phone?.includes(searchTerm)
  );

  if (loading) return (
    <div className="h-96 flex flex-col items-center justify-center gap-4">
      <Loader2 className="animate-spin text-emerald-500" size={40} />
      <p className="text-gray-500 font-black uppercase tracking-widest text-[10px]">Syncing Empire Data...</p>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      
      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-white uppercase tracking-tighter italic">Empire Registry</h2>
          <p className="text-gray-400 text-sm font-medium">Tracking everyone building the StoreLink future.</p>
        </div>
        <button onClick={fetchIntelligence} className="px-6 py-2 bg-gray-900 border border-gray-800 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:text-white transition-all flex items-center gap-2">
          <RefreshCcw size={14} /> Refresh Data
        </button>
      </div>

      {/* LEADERBOARDS (Champions vs Ambassadors) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <h3 className="text-sm font-black text-blue-400 uppercase tracking-widest flex items-center gap-2 px-2">
            <Users size={16} /> Waitlist Top 10
          </h3>
          <div className="bg-gray-900/40 border border-gray-800 rounded-[2rem] p-4">
            {waitlistRank.map((user, idx) => (
              <div key={user.email} className="flex justify-between items-center p-3 border-b border-white/5 last:border-0">
                <span className="text-[10px] font-black text-gray-600">#{idx + 1}</span>
                <p className="text-xs font-bold text-white flex-1 px-4 truncate">{user.business_name || user.email}</p>
                <p className="text-sm font-black text-blue-500 italic">{user.referral_count} Ref</p>
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <h3 className="text-sm font-black text-emerald-400 uppercase tracking-widest flex items-center gap-2 px-2">
            <Crown size={16} /> Vendor Top 10
          </h3>
          <div className="bg-gray-900/40 border border-gray-800 rounded-[2rem] p-4">
            {vendorRank.map((store, idx) => (
              <div key={store.name} className="flex justify-between items-center p-3 border-b border-white/5 last:border-0">
                <span className="text-[10px] font-black text-gray-600">#{idx + 1}</span>
                <p className="text-xs font-bold text-white flex-1 px-4 truncate">{store.name}</p>
                <p className="text-sm font-black text-emerald-500 italic">{store.referral_count} Ref</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* --- MASTER REGISTRY SECTION --- */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 px-2">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-amber-500/10 text-amber-500 rounded-xl border border-amber-500/20"><ListFilter size={20} /></div>
            <div>
              <h3 className="font-black text-xl text-white uppercase tracking-tighter italic">Combined Registry</h3>
              <p className="text-[9px] text-gray-500 font-black uppercase tracking-widest">{filteredRegistry.length} Total People</p>
            </div>
          </div>
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
            <input type="text" placeholder="Search by name, email or phone..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-gray-900 border border-gray-800 rounded-2xl py-3 pl-12 pr-4 text-sm text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all shadow-xl" />
          </div>
        </div>

        {/* --- SCROLLABLE TABLE AREA --- */}
        <div className="bg-gray-900/40 border border-gray-800 rounded-[2.5rem] overflow-hidden backdrop-blur-sm shadow-2xl">
          <div className="max-h-[600px] overflow-y-auto no-scrollbar">
            <table className="w-full text-left border-collapse">
              <thead className="bg-black sticky top-0 z-20 border-b border-gray-800">
                <tr>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic">User Identity</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic">Source</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic text-center">Refs</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-500 uppercase tracking-widest italic text-right">Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800/50">
                {filteredRegistry.map((entry, idx) => (
                  <tr key={`${entry.contact_email}-${idx}`} className="group hover:bg-emerald-500/5 transition-colors">
                    <td className="px-6 py-5">
                      <p className="text-sm font-black text-white uppercase tracking-tight italic">{entry.name}</p>
                      <div className="flex flex-col md:flex-row md:gap-4 mt-1">
                        <span className="text-[10px] text-gray-500 flex items-center gap-1 font-medium"><Mail size={10} className="text-blue-500" /> {entry.contact_email}</span>
                        <span className="text-[10px] text-gray-500 flex items-center gap-1 font-medium"><Phone size={10} className="text-emerald-500" /> {entry.contact_phone}</span>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <span className={`px-2 py-1 rounded-lg text-[8px] font-black uppercase ${entry.type === 'Live Vendor' ? 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20' : 'bg-blue-500/10 text-blue-500 border border-blue-500/20'}`}>
                        {entry.type}
                      </span>
                    </td>
                    <td className="px-6 py-5 text-center">
                      <div className={`text-sm font-black ${entry.score > 0 ? 'text-white' : 'text-gray-700'}`}>{entry.score}</div>
                    </td>
                    <td className="px-6 py-5 text-right">
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">
                        {new Date(entry.joined_at).toLocaleDateString('en-NG', { day: 'numeric', month: 'short' })}
                      </p>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {filteredRegistry.length === 0 && (
              <div className="p-20 text-center text-gray-600 font-black uppercase text-xs italic">No records found.</div>
            )}
          </div>
        </div>
      </div>

    </div>
  );
}